// Restore layouts/templates generated by v1.7.0's Adapter in the current library integration.
// Static assets are intercepted; candles are synthetic. No deployed-instance claim.
const { chromium } = require("@playwright/test");
const fs = require("node:fs"),
  path = require("node:path");
const { execFileSync } = require("node:child_process");
const assert = require("node:assert/strict");
const REPO = path.resolve(__dirname, "../.."),
  ROOT = path.join(REPO, "advanced-host");
const OUT =
  process.env.INDICATOR_COMPATIBILITY_OUTPUT ||
  "/tmp/mw-indicator-acceptance/compatibility.json";
const catalog = JSON.parse(
  execFileSync(
    path.join(REPO, ".venv/bin/python"),
    [
      "-c",
      "import json; from alerts.chart_indicators import public_catalog; print(json.dumps(public_catalog()))",
    ],
    {
      cwd: REPO,
      env: { ...process.env, PYTHONPATH: path.join(REPO, "backend") },
      encoding: "utf8",
    },
  ),
);
const baseline = execFileSync(
  "git",
  ["show", "62488c6:advanced-host/indicators.js"],
  { cwd: REPO, encoding: "utf8" },
).replace("function pythonStudies(", "function baselinePythonStudies(");
const report = {
  at: new Date().toISOString(),
  scope:
    "real v31 library; v1.7.0 Adapter-generated layouts/templates; synthetic candles",
  cases: [],
  errors: [],
};
const fixtureSymbol = process.env.INDICATOR_COMPAT_SYMBOL || "TEST";
(async () => {
  const browser = await chromium.launch({
    headless: true,
    args: ["--no-sandbox"],
    executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE,
  });
  const context = await browser.newContext({
      viewport: { width: 1440, height: 950 },
    }),
    page = await context.newPage();
  let savedState = null;
  page.on("pageerror", (e) => report.errors.push(e.message));
  page.on("console", (m) => {
    if (m.type() === "error") report.errors.push(m.text());
  });
  await page.route("https://indicator.test/**", (route) => {
    const url = new URL(route.request().url());
    if (url.pathname === "/")
      return route.fulfill({
        contentType: "text/html",
        body: `<!doctype html><html><head><meta charset="utf-8"></head><body style="margin:0"><div id="chart" style="height:100vh"></div>
      <script src="/charting_library/charting_library.js"></script><script src="/indicators.js"></script><script src="/baseline-indicators.js"></script><script src="/indicator-picker.js"></script><script>
      const catalog=${JSON.stringify(catalog)},legacy=${url.searchParams.has("baseline")}, savedState=${JSON.stringify(savedState)};
      const feed={onReady:cb=>setTimeout(()=>cb({supported_resolutions:['5']}),0),
        resolveSymbol:(name,cb)=>setTimeout(()=>cb({name,ticker:name,description:name,exchange:'TEST',type:'crypto',session:'24x7',timezone:'Etc/UTC',minmov:1,pricescale:100,has_intraday:true,supported_resolutions:['5'],volume_precision:0}),0),
        getBars:(symbol,res,period,cb)=>{const bars=[];for(let i=0;i<period.countBack;i++){const time=(period.to-period.countBack*300+i*300)*1000,close=100+Math.sin(i/10)*2;bars.push({time,open:close-1,high:close+2,low:close-2,close,volume:100});}setTimeout(()=>cb(bars,{noData:false}),0);},subscribeBars(){},unsubscribeBars(){}};
      const widget=new TradingView.widget({container:'chart',library_path:'/charting_library/',datafeed:feed,locale:'zh',symbol:${JSON.stringify(fixtureSymbol)},interval:'5',autosize:true,theme:'Dark',custom_css_url:'/chart-menu.css',saved_data:savedState||undefined,disabled_features:['header_indicators','use_localstorage_for_settings','create_volume_indicator_by_default'],custom_indicators_getter:async p=>(legacy?baselinePythonStudies:pythonStudies)(p,catalog)});
      let loaded=false,picker;widget.onChartReady(async()=>{await widget.headerReady();if(!legacy)picker=chartIndicatorPicker(widget,catalog,e=>{throw e;});loaded=true;});
      </script></body></html>`,
      });
    if (url.pathname === "/baseline-indicators.js")
      return route.fulfill({
        body: baseline,
        contentType: "application/javascript",
      });
    const file = path.join(ROOT, decodeURIComponent(url.pathname));
    if (!file.startsWith(ROOT + "/") || !fs.existsSync(file))
      return route.fulfill({ status: 404, body: "" });
    return route.fulfill({
      body: fs.readFileSync(file),
      contentType: file.endsWith(".js")
        ? "application/javascript"
        : file.endsWith(".css")
          ? "text/css"
          : file.endsWith(".html")
            ? "text/html"
            : "application/octet-stream",
    });
  });
  const settle = () =>
    page.waitForFunction(
      () =>
        typeof loaded !== "undefined" &&
        loaded &&
        widget.activeChart().dataReady(),
      null,
      { timeout: 30000 },
    );
  const snapshot = () =>
    page.evaluate(() =>
      widget
        .activeChart()
        .getAllStudies()
        .map((study) => {
          const api = widget.activeChart().getStudyById(study.id);
          return {
            id: study.id,
            name: study.name,
            inputs: api.getInputValues(),
            styles: api.getStyleValues(),
            visible: api.isVisible(),
          };
        }),
    );
  try {
    await page.goto("https://indicator.test/?baseline=1");
    await settle();
    await page.evaluate(async () => {
      for (const name of Object.keys(catalog)) {
        const inputs =
          name === "SMA"
            ? { period: 60 }
            : name === "BBANDS"
              ? { period: 25, deviation: 2.5 }
              : name === "MACD"
                ? { fast: 8, slow: 21, signal: 5 }
                : {};
        await widget
          .activeChart()
          .createStudy("守望 Python " + name, false, false, inputs);
      }
      const study = widget
        .activeChart()
        .getAllStudies()
        .find((s) => s.name === "守望 Python SMA");
      widget
        .activeChart()
        .getStudyById(study.id)
        .applyOverrides({ "value.color": "#ef5350", "value.linewidth": 3 });
      widget.activeChart().getStudyById(study.id).setVisible(false);
    });
    await page.waitForTimeout(500);
    const original = await snapshot();
    assert.equal(original.length, 8);
    const sma = original.find((s) => s.name === "守望 Python SMA");
    assert.equal(sma.styles.styles.plot0.color, "#ef5350");
    assert.equal(sma.styles.styles.plot0.linewidth, 3);
    savedState = await page.evaluate(
      () => new Promise((resolve) => widget.save(resolve)),
    );
    const template = await page.evaluate(() =>
      widget
        .activeChart()
        .createStudyTemplate({ saveSymbol: true, saveInterval: true }),
    );
    if (process.env.INDICATOR_COMPAT_FIXTURE)
      fs.writeFileSync(
        process.env.INDICATOR_COMPAT_FIXTURE,
        JSON.stringify({
          state: savedState,
          template,
          signature: original,
          symbol: fixtureSymbol,
        }),
      );
    await page.goto("https://indicator.test/");
    await settle();
    await page.waitForTimeout(500);
    const restored = await snapshot();
    assert.deepEqual(
      restored,
      original,
      "all persisted IDs, inputs, styles and visibility restore from the old Adapter",
    );
    report.cases.push(
      "v1.7.0 layout restores all 8 Python study identities, input order, numeric parameters, plot styles and visibility",
    );
    const ui = page.frames().find((f) => f !== page.mainFrame());
    await ui.getByRole("button", { name: "指标", exact: true }).click();
    const dialog = ui.getByRole("dialog", { name: "指标", exact: true });
    await dialog
      .getByRole("button", { name: "当前图表已添加", exact: true })
      .click();
    assert.equal(await dialog.locator("[data-instance-id]").count(), 8);
    await dialog.getByText("period=60", { exact: true }).waitFor();
    await dialog.getByRole("button", { name: "完成", exact: true }).click();
    await page.evaluate((template) => {
      widget
        .activeChart()
        .getAllStudies()
        .forEach((s) => widget.activeChart().removeEntity(s.id));
      widget.activeChart().applyStudyTemplate(template);
    }, template);
    await page.waitForFunction(
      () => widget.activeChart().getAllStudies().length === 8,
    );
    await page.waitForTimeout(500);
    const fromTemplate = await snapshot();
    const content = (studies) =>
      studies
        .map(({ id, ...rest }) => rest)
        .sort((a, b) => a.name.localeCompare(b.name));
    assert.deepEqual(
      content(fromTemplate),
      content(original),
      "old template preserves parameters, plot styles and visibility",
    );
    report.cases.push(
      "v1.7.0 study template restores all 8 indicators and their settings",
    );
    const macd = fromTemplate.find((s) => s.name === "守望 Python MACD");
    assert.equal(
      macd.styles.styles.plot2.plottype,
      1,
      "MACD histogram keeps its persisted plot index",
    );
    report.cases.push(
      "MACD histogram stays plot2; BBANDS floating deviation stays 2.5",
    );
    assert.deepEqual(report.errors, []);
    console.log(
      "Legacy layouts/templates: all 8 indicator IDs, inputs, styles and visibility passed",
    );
  } finally {
    fs.writeFileSync(OUT, JSON.stringify(report, null, 2));
    await browser.close();
  }
})().catch((error) => {
  console.error(error);
  process.exit(1);
});
